// The commands of the runtime, from tests/suite/functions.txt (the list that the wiki is built from, installed as commands.txt).
#pragma once
#include <filesystem>
#include <map>
#include <string>
#include <vector>

namespace blitz::lsp {
	struct command_parameter {
		std::string name;
		std::string type;     // Int, Float, String, Int64, UInt64
		std::string fallback; // Default value as written, empty if the parameter is required
		bool        optional = false;
		bool        out      = false;
	};

	struct command {
		std::string                    name;   // As written in the manuals
		std::string                    module; // blitz3d, graphics, plusgui ...
		std::string                    returns; // Empty if nothing
		std::vector<command_parameter> parameters;

		/** `Name(width:Int, height:Int, flags:Int = 0):Int` */
		std::string signature() const;
	};

	class command_table {
		std::map<std::string, command> _by_name; // Lower case name
		public:
		/** Reads the file. Returns how many commands there are, 0 if the file is missing. */
		size_t load(std::filesystem::path const& file);
		command const* find(std::string const& lower_name) const;
		std::map<std::string, command> const& all() const { return _by_name; }
	};
} // namespace blitz::lsp
